// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        c = new DnGmxBatchingManager();
    }

    function testFuzz_property(address initializer, address claimer, uint256 amount) public {
        // keep the initializer in the admissible domain (any real account)
        vm.assume(initializer != address(0));
        vm.assume(initializer != address(this));

        // deploy a minimal glpManager so initialize can read vault()
        GlpMgr mgr = new GlpMgr();

        // initialize via low-level call to avoid cross-file interface-type identity issues
        vm.prank(initializer);
        (bool initOk, ) = address(c).call(
            abi.encodeWithSignature(
                "initialize(address,address,address,address,address,address)",
                address(1), // sGlp
                address(2), // usdc
                address(3), // rewardRouter
                address(mgr), // glpManager
                address(5), // dnGmxJuniorVault
                address(6) // keeper
            )
        );
        assertTrue(initOk, "initialize must succeed");

        // arbitrary subsequent interaction from a fuzzed caller (claim attempt, may revert)
        vm.prank(claimer);
        try c.claim(claimer, amount) {
            // may succeed; irrelevant to the property
        } catch {
            // expected to revert for uninitialized state; irrelevant
        }

        // GENERAL RULE: after initialization by an account, the owner recorded by the
        // contract is that account and is stable across arbitrary later calls.
        // The mutant returns address(0) unconditionally, breaking this for any nonzero initializer.
        assertTrue(c.owner() == initializer, "owner must remain the initializer");
    }
}

// minimal adversarial-environment helper: glpManager whose vault() is readable
contract GlpMgr {
    function vault() external pure returns (address) {
        return address(1);
    }
}
